            ds.ebitdaMargin = Math.min(15, Math.max(3, 7.8 + (ds.financialScore - 45) * 0.12));
            ds.nps = Math.round(12 + (ds.customerScore - 40) * 0.7);
            ds.retention = Math.min(99, Math.max(70, 88 + (ds.customerScore - 40) * 0.18));

            ds.compositeHistory.push(Math.round(composite * 10) / 10);
            ds.financialHistory.push(Math.round(ds.financialScore * 10) / 10);
            ds.customerHistory.push(Math.round(ds.customerScore * 10) / 10);
            ds.processHistory.push(Math.round(ds.processScore * 10) / 10);
            ds.lgHistory.push(Math.round(ds.lgScore * 10) / 10);

            // platform score: composite is already the 0-100 metric getPerformanceSummary reads for the final tier, so reuse it directly, clamped
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(composite))) });

            var self = this;
            setTimeout(function() {
                self._updateEventPanel(ds.lastEventText);
            }, 500);

            return {
                period: state.currentPeriod,
                financialScore: Math.round(ds.financialScore * 10) / 10,
                customerScore: Math.round(ds.customerScore * 10) / 10,
                processScore: Math.round(ds.processScore * 10) / 10,
                lgScore: Math.round(ds.lgScore * 10) / 10,
                composite: Math.round(composite * 10) / 10,
                ebitdaMargin: Math.round(ds.ebitdaMargin * 10) / 10,
                nps: ds.nps,
                retention: Math.round(ds.retention * 10) / 10,
                budgetUsed: 4.5
            };
        }

