        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var composites = history.map(function(r) { return r.results ? r.results.composite : 0; });
            var finalComposite = composites[composites.length - 1] || 0;
            var avgComposite = composites.reduce(function(s, v) { return s + v; }, 0) / composites.length;

            var t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var performance = t('perf_needs');
            if (finalComposite >= 47 && avgComposite >= 42) performance = t('perf_good');
            if (finalComposite >= 53 && avgComposite >= 45) performance = t('perf_excellent');
            if (finalComposite >= 58 && avgComposite >= 47) performance = t('perf_outstanding');

            var insights = [];
            if (last && last.results) {
                if (last.results.lgScore > 70) insights.push(t('insight_lg_strong'));
                if (last.results.financialScore > 70) insights.push(t('insight_fin_strong'));
                if (last.results.customerScore < 50) insights.push(t('insight_cust_weak'));
                if (last.results.processScore < 50) insights.push(t('insight_proc_weak'));
            }
            if (insights.length === 0) insights.push(t('insight_default'));

            return {
                finalComposite: finalComposite,
                avgComposite: Math.round(avgComposite * 10) / 10,
                ebitdaMargin: last && last.results ? last.results.ebitdaMargin : 7.8,
                nps: last && last.results ? last.results.nps : 12,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            if (results.composite < 35) return window.mySimulation.t('hint_critical');
            if (results.lgScore < 30) return window.mySimulation.t('hint_lg_low');
            if (results.financialScore < 35 && state.currentPeriod <= 4) return window.mySimulation.t('hint_patience');
            if (results.composite > 65) return window.mySimulation.t('hint_good');
            return null;
        }

